Lemma addressable_rd : forall m A n a w,
  addressable m A n -> A <= a -> 1 <= w -> a + w <= A + 8 * (n / 8) ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m A n a w T Ha Hw Hhi. pose proof T as [Hn0 (P0 & _ & _)].
